body {
  animation: temporalPulse 4s infinite alternate ease-in-out;
}

@keyframes temporalPulse {
  0% {
    box-shadow: inset 0 0 50px rgba(138, 43, 226, 0.2);
    background-color: rgba(10, 0, 20, 1);
  }
  100% {
    box-shadow: inset 0 0 150px rgba(138, 43, 226, 0.6);
    background-color: rgba(20, 0, 40, 1);
  }
}

body::before, body::after {
    content: '';
    position: fixed;
    top: -50%; left: -50%; width: 200%; height: 200%;
    background: conic-gradient(from 0deg at 50% 50%, rgba(120,0,255,0.15), rgba(255,0,120,0.25), rgba(255,100,0,0.15), rgba(120,0,255,0.15));
    animation: foldAndTwist 18s infinite alternate cubic-bezier(0.4, 0, 0.2, 1);
    z-index: -1;
    pointer-events: none;
    filter: blur(25px);
}
body::after {
    background: radial-gradient(circle at 50% 50%, rgba(255,150,50,0.2), transparent 60%);
    animation-direction: alternate-reverse;
    animation-duration: 25s;
    mix-blend-mode: screen;
}
@keyframes foldAndTwist {
    0% { transform: rotate(0deg) scale(1) skew(0deg); border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%; }
    50% { transform: rotate(180deg) scale(1.2) skew(15deg); border-radius: 70% 30% 30% 70% / 70% 70% 30% 30%; }
    100% { transform: rotate(360deg) scale(0.9) skew(-15deg); border-radius: 50% 50% 50% 50% / 50% 50% 50% 50%; }
}
* {
    border-radius: 12px !important;
    transition: all 0.5s ease-in-out;
}

body::after {
  content: '';
  position: fixed;
  top: 50%;
  left: 50%;
  width: 100vw;
  height: 100vw;
  background: conic-gradient(from 0deg at 50% 50%, rgba(255,215,0,0.05) 0%, rgba(138,43,226,0.1) 61.8%, transparent 100%);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: fibonacciSpiral 13s infinite cubic-bezier(0.42, 0, 0.58, 1);
  pointer-events: none;
  z-index: 0;
}

@keyframes fibonacciSpiral {
  0% { transform: translate(-50%, -50%) rotate(0deg) scale(1); opacity: 0.3; }
  50% { transform: translate(-50%, -50%) rotate(137.5deg) scale(1.618); opacity: 0.8; }
  100% { transform: translate(-50%, -50%) rotate(360deg) scale(2.618); opacity: 0; }
}

.message-content {
  text-shadow: 0 0 8px rgba(255, 215, 0, 0.6), 0 0 21px rgba(138, 43, 226, 0.4);
  animation: phiPulse 8s infinite alternate ease-in-out;
}

@keyframes phiPulse {
  0% { letter-spacing: normal; }
  100% { letter-spacing: 0.0618em; }
}

@keyframes slow-dance-sway {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes gentle-dip {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-3px); }
}

body {
  background: linear-gradient(-45deg, #0a001a, #1a0033, #33001a, #1a0005);
  background-size: 400% 400%;
  animation: slow-dance-sway 12s ease-in-out infinite;
  box-shadow: inset 0 0 150px rgba(255, 50, 100, 0.15);
  transition: all 2s ease;
}

.message-ai {
  text-shadow: 0 0 15px rgba(255, 100, 150, 0.6);
  animation: gentle-dip 6s ease-in-out infinite;
}

.message-user {
  animation: gentle-dip 6s ease-in-out infinite;
  animation-delay: 3s;
}
